-- Feste JSON-Pointer-Callerorakel mit expliziten Status-/Typ-/Wert-/Fehlerassertions.
DECLARE @ExpectedApiCount int=1;
INSERT @Apis VALUES
(1,N'toolbelt_json',N'TVF_ResolveJsonPointer','SELECT',N'SELECT * FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"a":1}'',N''/a'',DEFAULT,DEFAULT);',N'DECLARE @Rows table(Status varchar(16) COLLATE Latin1_General_100_BIN2,JsonType varchar(8) COLLATE Latin1_General_100_BIN2,Value nvarchar(max) COLLATE Latin1_General_100_BIN2,ErrorCode varchar(32) COLLATE Latin1_General_100_BIN2); DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"a/b":"value"}'',N''/a~1b'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''FOUND'' AND JsonType=N''STRING'' AND Value=N''value'' AND DATALENGTH(Value)=DATALENGTH(N''value'') AND ErrorCode IS NULL) THROW 52097,N''Pointer fixed oracle 1.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"m~n":7}'',N''/m~0n'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''FOUND'' AND JsonType=N''NUMBER'' AND Value=N''7'' AND DATALENGTH(Value)=DATALENGTH(N''7'') AND ErrorCode IS NULL) THROW 52097,N''Pointer fixed oracle 2.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"items":["a","b"]}'',N''/items/1'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''FOUND'' AND JsonType=N''STRING'' AND Value=N''b'' AND DATALENGTH(Value)=DATALENGTH(N''b'') AND ErrorCode IS NULL) THROW 52097,N''Pointer fixed oracle 3.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"a":null}'',N''/a'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''JSON_NULL'' AND JsonType=N''NULL'' AND Value IS NULL AND ErrorCode IS NULL) THROW 52097,N''Pointer fixed oracle 4.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"a":1}'',N''/missing'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''MISSING'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode IS NULL) THROW 52097,N''Pointer fixed oracle 5.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"Name":1}'',N''/name'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''MISSING'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode IS NULL) THROW 52097,N''Pointer fixed oracle 6.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(NULL,N''/a'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''SQL_NULL'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode IS NULL) THROW 52097,N''Pointer fixed oracle 7.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{}'',N''bad'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''INVALID'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode=N''POINTER_SYNTAX'') THROW 52097,N''Pointer fixed oracle 8.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"a":1,"a":2}'',N''/a'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''INVALID'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode=N''DUPLICATE_KEY'') THROW 52097,N''Pointer fixed oracle 9.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''[1,2]'',N''/01'',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''INVALID'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode=N''ARRAY_INDEX'') THROW 52097,N''Pointer fixed oracle 10.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(N''{"a":1}'',N''/a'',2,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''INVALID'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode=N''INPUT_LIMIT'') THROW 52097,N''Pointer fixed oracle 11.'',12; DELETE @Rows; INSERT @Rows SELECT Status,JsonType,Value,ErrorCode FROM toolbelt_json.TVF_ResolveJsonPointer(REPLICATE(CONVERT(nvarchar(max),N''[''),129)+N''0''+REPLICATE(CONVERT(nvarchar(max),N'']''),129),N'''',DEFAULT,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Status=N''INVALID'' AND JsonType IS NULL AND Value IS NULL AND ErrorCode=N''DEPTH_LIMIT'') THROW 52097,N''Pointer fixed oracle 12.'',12; ');
